/**
 * Review reproducer for candidate 5: the cost-first QueryJoinOptimizer places a Cartesian product inside a fully
 * connected join graph when cold-start estimates are all close to one row.
 */
class QueryJoinCrossProductReviewReproTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void connectedChainMustNotBeOrderedWithACrossProductUnderNearUnitEstimates() {
		double[] cardinalities = { 1.0d, 1.05d, 1.1d, 1.2d, 1.3d };
		Map<String, String> crossProductPlans = new TreeMap<>();
		int plans = 0;
		for (List<Double> assignment : permutations(cardinalities)) {
			Map<String, Double> byPredicate = Map.of("p1", assignment.get(0), "p2", assignment.get(1), "p3",
					assignment.get(2), "p4", assignment.get(3), "p5", assignment.get(4));
			// connected chain ?a p1 ?b p2 ?c p3 ?d p4 ?e p5 ?f
			TupleExpr chain = new QueryRoot(new Join(sp("a", "p1", "b"), new Join(sp("b", "p2", "c"),
					new Join(sp("c", "p3", "d"), new Join(sp("d", "p4", "e"), sp("e", "p5", "f"))))));
			new QueryJoinOptimizer(new FixedStatistics(byPredicate), new EmptyTripleSource()).optimize(chain, null,
					EmptyBindingSet.getInstance());
			plans++;
			List<StatementPattern> order = StatementPatternCollector.process(chain);
			Set<String> bound = new HashSet<>();
			StringBuilder rendered = new StringBuilder();
			boolean crossProduct = false;
			for (StatementPattern pattern : order) {
				Set<String> vars = Set.of(pattern.getSubjectVar().getName(), pattern.getObjectVar().getName());
				if (!bound.isEmpty() && vars.stream().noneMatch(bound::contains)) {
					crossProduct = true;
					rendered.append(" X ");
				} else if (!bound.isEmpty()) {
					rendered.append(" . ");
				}
				rendered.append(pattern.getPredicateVar().getValue().stringValue());
				bound.addAll(vars);
			}
			if (crossProduct) {
				crossProductPlans.put(byPredicate.toString(), rendered.toString());
			}
		}
		assertTrue(crossProductPlans.isEmpty(), crossProductPlans.size() + " of " + plans
				+ " near-unit estimate assignments order a connected chain with a Cartesian product: "
				+ crossProductPlans);
	}

	@Test
	void connectedChainWithCheapEndpointsMustNotBeOrderedWithACrossProduct() {
		// cold start: two predicates unknown to statistics are estimated at one row, the middle is large
		Map<String, String> qjoCross = new TreeMap<>();
		Map<String, String> packedCross = new TreeMap<>();
		List<Map<String, Double>> assignments = List.of(
				Map.of("p1", 1.0d, "p2", 1_000.0d, "p3", 1_000.0d, "p4", 1_000.0d, "p5", 1.0d),
				Map.of("p1", 1.0d, "p2", 100.0d, "p3", 10_000.0d, "p4", 100.0d, "p5", 1.0d),
				Map.of("p1", 1.0d, "p2", 50.0d, "p3", 50.0d, "p4", 1.0d, "p5", 50.0d),
				Map.of("p1", 2.0d, "p2", 1_000.0d, "p3", 1.0d, "p4", 1_000.0d, "p5", 2.0d));
		for (Map<String, Double> byPredicate : assignments) {
			TupleExpr chain = new QueryRoot(chain());
			new QueryJoinOptimizer(new FixedStatistics(byPredicate), new EmptyTripleSource()).optimize(chain, null,
					EmptyBindingSet.getInstance());
			String qjo = crossProductOrder(chain);
			if (qjo != null) {
				qjoCross.put(byPredicate.toString(), qjo);
			}
			org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedPlanningResult packed = org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedCascadesPlanner
					.optimize(chain(), org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal
							.root(), (query, relationId) -> {
								if (!query.isStatementPattern(relationId)) {
									return Double.NaN;
								}
								String predicate = query.statementPatternValue(relationId, 1).stringValue()
										.substring("urn:".length());
								return byPredicate.getOrDefault(predicate, Double.NaN);
							});
			String packedOrder = crossProductOrder(packed.selectedPlan());
			if (packedOrder != null) {
				packedCross.put(byPredicate.toString(), packedOrder);
			}
		}
		assertTrue(qjoCross.isEmpty() && packedCross.isEmpty(),
				"QueryJoinOptimizer cross products: " + qjoCross + " | packed cross products: " + packedCross);
	}

	private static TupleExpr chain() {
		return new Join(sp("a", "p1", "b"), new Join(sp("b", "p2", "c"),
				new Join(sp("c", "p3", "d"), new Join(sp("d", "p4", "e"), sp("e", "p5", "f")))));
	}

	/**
	 * Returns the rendered evaluation order if some pattern shares no variable with every pattern evaluated before it
	 * (a Cartesian product at execution time, since bindings flow left-to-right), otherwise null.
	 */
	private static String crossProductOrder(TupleExpr plan) {
		Set<String> bound = new HashSet<>();
		StringBuilder rendered = new StringBuilder();
		boolean cross = false;
		for (StatementPattern pattern : StatementPatternCollector.process(plan)) {
			Set<String> vars = Set.of(pattern.getSubjectVar().getName(), pattern.getObjectVar().getName());
			if (!bound.isEmpty() && vars.stream().noneMatch(bound::contains)) {
				cross = true;
				rendered.append(" X ");
			} else if (!bound.isEmpty()) {
				rendered.append(" . ");
			}
			rendered.append(pattern.getPredicateVar().getValue().stringValue().substring(4));
			bound.addAll(vars);
		}
		return cross ? rendered.toString() : null;
	}

	private static List<List<Double>> permutations(double[] values) {
		List<List<Double>> result = new ArrayList<>();
		List<Double> working = new ArrayList<>();
		for (double value : values) {
			working.add(value);
		}
		permute(working, 0, result);
		return result;
	}

	private static void permute(List<Double> values, int offset, List<List<Double>> result) {
		if (offset == values.size()) {
			result.add(List.copyOf(values));
			return;
		}
		for (int i = offset; i < values.size(); i++) {
			java.util.Collections.swap(values, offset, i);
			permute(values, offset + 1, result);
			java.util.Collections.swap(values, offset, i);
		}
	}

	private static StatementPattern sp(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_const_" + predicate, VF.createIRI("urn:" + predicate),
				false, true), Var.of(object));
	}

	private static final class FixedStatistics extends EvaluationStatistics {
		private final Map<String, Double> byPredicate;

		private FixedStatistics(Map<String, Double> byPredicate) {
			this.byPredicate = byPredicate;
		}

		@Override
		public double getCardinality(TupleExpr expr) {
			if (expr instanceof StatementPattern pattern && pattern.getPredicateVar().hasValue()) {
				String predicate = pattern.getPredicateVar().getValue().stringValue().substring("urn:".length());
				Double value = byPredicate.get(predicate);
				if (value != null) {
					return value;
				}
			}
			return super.getCardinality(expr);
		}
	}
}
